import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { ConfirmExitGuard } from '../../../shared/guards/confirm-exit.guard';
import { PermissionGuard } from '../../../core/guard/permission/permission.guard';


const routes: Routes = [

  { path: '', redirectTo: 'filesaction', pathMatch: 'full' },
  { path: 'filesaction/:id', loadComponent: () => import('../../components/myfiles/filesaction/filesaction.component').then(m => m.FilesactionComponent), canDeactivate: [ConfirmExitGuard],
    data: { permission: 'VC' },
    canActivate: [PermissionGuard]
   },
  {
    path: 'workspace/:id',
    loadComponent: () => import('../../components/workspace/workspace.component').then(m => m.WorkspaceComponent),
    data: { permission: 'WS' },
    canActivate: [PermissionGuard],

  },
  {
    path: 'task/:id',
    loadComponent: () => import('../../components/task/task.component').then(m => m.TaskComponent),
    data: { permission: 'TS' },
    canActivate: [PermissionGuard],
  },
  { path: 'factcontact/:id', loadComponent: () => import('../../components/factcontact/factcontact.component').then(m => m.FactcontactComponent),
    data: { permission: 'CT' },
    canActivate: [PermissionGuard],
   },
  {
    path: 'export/:id',
    loadComponent: () => import('../../components/myfiles/export/export.component').then(m => m.ExportComponent),
    data: { permission: 'ED' },
    canActivate: [PermissionGuard],
  },
  { path: 'download/:id', loadComponent: () => import('../../components/myfiles/download-section/download/download.component').then(m => m.DownloadComponent) },
];
@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class MyfilesRoutingModule {

}
